<style>
    .rphi{--wine:#3b0718;--red:#922c43;--line:#ead7dc;--muted:#786971;color:#38252b;padding:10px 0 32px}.rphi-hero{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:8px 0 20px;padding:25px 28px;border-radius:16px;color:#fff;background:linear-gradient(120deg,var(--wine),#68182f 60%,var(--red));box-shadow:0 10px 25px rgba(59,7,24,.14)}.rphi-hero h1{margin:0 0 6px;color:#fff;font-size:24px}.rphi-hero p{margin:0;color:#f1dce1;font-size:13px}.rphi-hero .rphi-label{font-size:10px;text-transform:uppercase;letter-spacing:.08em;font-weight:800;color:#f1dce1}.rphi-hero .rphi-year{font-size:21px;font-weight:800}.rphi-actions{display:flex;gap:8px;align-items:center}.rphi-actions .btn{border-radius:8px;font-weight:700}.rphi-filter{display:flex;align-items:end;gap:10px;margin:0 0 18px;padding:15px 18px;border:1px solid var(--line);border-radius:13px;background:#fff;box-shadow:0 4px 15px rgba(59,7,24,.04)}.rphi-filter label{display:block;margin-bottom:5px;color:#59454c;font-size:11px;font-weight:700}.rphi-filter select{height:38px;min-width:170px;border:1px solid #dfcbd1;border-radius:7px}.rphi-filter button{height:38px;border-radius:7px}.rphi-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:18px}.rphi-metric{padding:16px 18px;border:1px solid var(--line);border-radius:13px;background:#fff;box-shadow:0 4px 15px rgba(59,7,24,.04)}.rphi-metric span{display:block;color:var(--muted);font-size:10px;font-weight:800;letter-spacing:.05em;text-transform:uppercase}.rphi-metric strong{display:block;margin-top:7px;color:var(--wine);font-size:25px;line-height:1}.rphi-metric small{display:block;margin-top:7px;color:var(--muted);font-size:11px}.rphi-card{overflow:hidden;margin-bottom:18px;border:1px solid var(--line);border-radius:14px;background:#fff;box-shadow:0 5px 17px rgba(59,7,24,.045)}.rphi-card-head{padding:15px 18px;border-bottom:1px solid #f0e4e7;background:#fdf9fa}.rphi-card-head h2{margin:0;color:var(--wine);font-size:15px;font-weight:800}.rphi-card-head p{margin:4px 0 0;color:var(--muted);font-size:11px}.rphi-table-wrap{overflow:auto}.rphi-table{min-width:780px;margin:0}.rphi-table th{padding:10px 12px;border-top:0;background:#fbf4f5;color:#70545d;font-size:10px;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}.rphi-table td{padding:11px 12px;border-color:#f1e8ea;font-size:12px;vertical-align:middle}.rphi-table tr:hover{background:#fdf9fa}.rphi-pill{display:inline-block;padding:4px 7px;border-radius:20px;background:#f8eef0;color:#713449;font-size:10px;font-weight:700}.rphi-num{text-align:right;font-weight:700;font-variant-numeric:tabular-nums}.rphi-empty{padding:24px!important;color:var(--muted);text-align:center}.rphi-sr-only{position:absolute;left:-9999px}
    @media(max-width:767px){.rphi-hero{align-items:flex-start;flex-direction:column;padding:21px}.rphi-hero h1{font-size:20px}.rphi-actions{width:100%}.rphi-actions .btn{flex:1}.rphi-filter{align-items:stretch;flex-direction:column}.rphi-filter select{width:100%}.rphi-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.rphi-metric{padding:13px}.rphi-metric strong{font-size:22px}}
    @media print{body{background:#fff!important}.rphi{padding:0}.rphi-hero{padding:14px 18px;box-shadow:none;-webkit-print-color-adjust:exact;print-color-adjust:exact}.rphi-actions,.rphi-filter,.no-print{display:none!important}.rphi-card,.rphi-metric{break-inside:avoid;box-shadow:none}.rphi-card{margin-bottom:10px}.rphi-table{min-width:0;font-size:9px}.rphi-table th,.rphi-table td{padding:6px}.rphi-table-wrap{overflow:visible}.rphi-table{width:100%;table-layout:auto}}
</style>
<div class="container-fluid rphi">
    <header class="rphi-hero"><div><div class="rphi-label"><i class="mdi mdi-map-marker-radius-outline mr-1"></i> Regional submission dashboard</div><h1>Phil-IRI KS2 Regional Report</h1><p>Consolidated school submissions for Key Stage 2, Grades 4–6.</p></div><div class="rphi-actions"><div><div class="rphi-label">School Year</div><div class="rphi-year"><?= html_escape($school_year_label); ?></div></div><button type="button" class="btn btn-light" onclick="window.print()"><i class="mdi mdi-printer-outline mr-1"></i>Print / Save PDF</button></div></header>

    <form method="get" action="<?= base_url('Pages/regional_phil_iri_report'); ?>" class="rphi-filter no-print"><div><label for="rphi-sy">School Year</label><select id="rphi-sy" name="sy" class="form-control"><?php for ($year=(int)date('Y')+2; $year>=2023; $year--): ?><option value="<?= $year; ?>" <?= $year === (int)$school_year ? 'selected' : ''; ?>><?= ($year-1).'-'.$year; ?></option><?php endfor; ?></select></div><button class="btn btn-primary" type="submit"><i class="mdi mdi-filter-outline mr-1"></i>Generate Report</button></form>

    <section class="rphi-metrics" aria-label="Regional Phil-IRI summary">
        <div class="rphi-metric"><span>Schools submitted</span><strong><?= number_format($reported_school_count); ?></strong><small>of <?= number_format($regional_school_count); ?> schools in the region</small></div>
        <div class="rphi-metric"><span>Learner assessment entries</span><strong><?= number_format($totals['learners_assessed']); ?></strong><small>Counts may repeat across grades, languages, or test periods</small></div>
        <div class="rphi-metric"><span>Independent readers</span><strong><?= number_format($totals['independent']); ?></strong><small><?= $totals['learners_assessed'] > 0 ? number_format(($totals['independent']/$totals['learners_assessed'])*100,1).'%' : '0.0%'; ?> of reported learner assessment entries</small></div>
        <div class="rphi-metric"><span>Needs reading support</span><strong><?= number_format($totals['instructional']+$totals['frustration']+$totals['non_reader']); ?></strong><small>Instructional, frustration, and non-reader totals</small></div>
    </section>

    <section class="rphi-card"><div class="rphi-card-head"><h2>Results by grade, language, and assessment period</h2><p>Counts are summed from school submissions for <?= html_escape($school_year_label); ?>.</p></div><div class="rphi-table-wrap"><table class="table rphi-table"><thead><tr><th>Grade</th><th>Language</th><th>Assessment</th><th>Schools</th><th>Learners assessed</th><th>Independent</th><th>Instructional</th><th>Frustration</th><th>Non-reader</th></tr></thead><tbody><?php if (empty($groups)): ?><tr><td colspan="9" class="rphi-empty">No school submissions were found for this school year.</td></tr><?php else: foreach ($groups as $group): ?><tr><td><strong>Grade <?= (int)$group['grade_level']; ?></strong></td><td><span class="rphi-pill"><?= html_escape($group['language']); ?></span></td><td><?= html_escape($group['assessment_period']); ?></td><td class="rphi-num"><?= number_format((int)$group['school_count']); ?></td><td class="rphi-num"><?= number_format((int)$group['learners_assessed']); ?></td><td class="rphi-num"><?= number_format((int)$group['independent']); ?></td><td class="rphi-num"><?= number_format((int)$group['instructional']); ?></td><td class="rphi-num"><?= number_format((int)$group['frustration']); ?></td><td class="rphi-num"><?= number_format((int)$group['non_reader']); ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>

    <section class="rphi-card"><div class="rphi-card-head"><h2>Summary by division</h2><p>Only divisions and schools in your assigned region are included.</p></div><div class="rphi-table-wrap"><table class="table rphi-table"><thead><tr><th>Division</th><th>Schools submitted</th><th>Learners assessed</th><th>Independent</th><th>Instructional</th><th>Frustration</th><th>Non-reader</th></tr></thead><tbody><?php if (empty($divisions)): ?><tr><td colspan="7" class="rphi-empty">Division summaries will appear after schools submit results.</td></tr><?php else: foreach ($divisions as $division): ?><tr><td><strong><?= html_escape($division['name']); ?></strong></td><td class="rphi-num"><?= number_format((int)$division['school_count']); ?></td><td class="rphi-num"><?= number_format((int)$division['learners_assessed']); ?></td><td class="rphi-num"><?= number_format((int)$division['independent']); ?></td><td class="rphi-num"><?= number_format((int)$division['instructional']); ?></td><td class="rphi-num"><?= number_format((int)$division['frustration']); ?></td><td class="rphi-num"><?= number_format((int)$division['non_reader']); ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>

    <section class="rphi-card"><div class="rphi-card-head"><h2>School submissions</h2><p>Detailed school-level records included in this report.</p></div><div class="rphi-table-wrap"><table class="table rphi-table"><thead><tr><th>Division</th><th>School</th><th>Grade</th><th>Language</th><th>Assessment</th><th>Learners assessed</th><th>Independent</th><th>Instructional</th><th>Frustration</th><th>Non-reader</th></tr></thead><tbody><?php if (empty($records)): ?><tr><td colspan="10" class="rphi-empty">No school submissions were found for this school year.</td></tr><?php else: foreach ($records as $record): ?><tr><td><?= html_escape($record->division_name); ?></td><td><?= html_escape($record->schoolName); ?></td><td>Grade <?= (int)$record->grade_level; ?></td><td><?= html_escape($record->language); ?></td><td><?= html_escape($record->assessment_period); ?></td><td class="rphi-num"><?= number_format((int)$record->learners_assessed); ?></td><td class="rphi-num"><?= number_format((int)$record->independent); ?></td><td class="rphi-num"><?= number_format((int)$record->instructional); ?></td><td class="rphi-num"><?= number_format((int)$record->frustration); ?></td><td class="rphi-num"><?= number_format((int)$record->non_reader); ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
</div>
